import { Suspense, lazy } from 'react'

import { ItemSuspense } from '~/ui/layout/item/ItemCard'
import type { CommonCardProp } from '~/ui/items/common'

import { name } from './name'

const ItemCard = lazy(() => import('./ItemCard'));


export function DanceHoll(prop: CommonCardProp) {
  return (
    <Suspense fallback={<ItemSuspense id={name.id} />}>
      <ItemCard id={name.id} {...prop} />
    </Suspense>
  )
}

